using System.IO;
using System.Text;
using System.Windows;
using SmoothCoder.App.Services;

namespace SmoothCoder.Tests;

/// <summary>Guards the wiring between <see cref="VoiceNotificationService"/>'s cue list, the WAV files
/// generated by <c>scripts/generate-voice.ps1</c>, and the <c>&lt;Resource&gt;</c> entry in the csproj.
///
/// <para>Worth a test because the failure is silent: a renamed, un-generated, or un-embedded asset
/// makes <c>LoadAsset</c> fall back to a plain beep, which still plays, so nothing looks broken until
/// someone is relying on hearing which agent the task moved to at 3am.</para></summary>
public class VoiceAssetTests
{
    public static TheoryData<VoiceCue> AllCues()
    {
        var data = new TheoryData<VoiceCue>();
        foreach (var cue in Enum.GetValues<VoiceCue>())
        {
            data.Add(cue);
        }

        return data;
    }

    [Theory]
    [MemberData(nameof(AllCues))]
    public void EveryCue_HasAnEmbeddedWavThatWavAudioCanScale(VoiceCue cue)
    {
        // The same URI the service resolves at runtime, not a re-spelled copy of it.
        var resource = Application.GetResourceStream(VoiceNotificationService.AssetUri(cue));
        Assert.NotNull(resource);

        using var buffer = new MemoryStream();
        resource.Stream.CopyTo(buffer);
        var wav = buffer.ToArray();

        Assert.Equal("RIFF", Encoding.ASCII.GetString(wav, 0, 4));
        Assert.Equal("WAVE", Encoding.ASCII.GetString(wav, 8, 4));

        // Scale returns its input unchanged when it can't read the format, so a changed encoder
        // setting (say, 24-bit or IEEE float output) would leave the volume slider silently inert.
        var scaled = WavAudio.Scale(wav, 0.25);
        Assert.NotSame(wav, scaled);
        Assert.Equal(wav.Length, scaled.Length);

        // Streaming encoder headers declare uint.MaxValue. In-memory playback fails on those
        // lengths even though file-backed readers can play the same asset.
        using var playback = new NAudio.Wave.WaveFileReader(new MemoryStream(WavAudio.NormalizeLengths(wav)));
        Assert.InRange(playback.Length, 1L, wav.Length);
        Assert.InRange(playback.TotalTime.TotalSeconds, 0.1, 30);
    }

    [Theory]
    [InlineData(SmoothCoder.App.Models.AgentKind.ClaudeCode, VoiceCue.HandoffToClaude)]
    [InlineData(SmoothCoder.App.Models.AgentKind.CodexCli, VoiceCue.HandoffToCodex)]
    public void HandoffCueFor_NamesTheAgentBeingStarted(SmoothCoder.App.Models.AgentKind target, VoiceCue expected)
    {
        Assert.Equal(expected, VoiceNotificationService.HandoffCueFor(target));
    }

    [Theory]
    [InlineData(SmoothCoder.App.Models.AgentKind.KimiCodeCli)]
    [InlineData(SmoothCoder.App.Models.AgentKind.AntigravityCli)]
    public void HandoffCueFor_AgentThatDoesNotTakePartInHandoffs_IsNull(SmoothCoder.App.Models.AgentKind target)
    {
        Assert.Null(VoiceNotificationService.HandoffCueFor(target));
    }
}
